    "meaning": {
      "prompt": "つよいかせで大きな木のえだが＿＿＿しまった。",
      "options": [
        "おれて",
        "こわれて",
        "たおれて",
        "やぶれて"
      ],
      "answerIndex": 0
    },
    "optionExplanations": [
      "「折れて」（折斷）是樹枝斷裂的自然搭配詞，為正解。",
      "「こわれて」（壊れる，機器・物品損壊）通常不用於形容樹枝，錯誤。",
      "「たおれて」（倒れる，整棵樹或人倒下）跟「木の枝（樹枝）」搭配不自然，通常整棵樹才用「倒れる」，錯誤。",
      "「やぶれて」（破れる，紙、布等破裂）不用於樹枝，錯誤。"
    ]
